CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name varchar(150) NOT NULL,sku varchar(80),sale_price_cents integer NOT NULL CHECK(sale_price_cents>=0),cost_price_cents integer NOT NULL DEFAULT 0 CHECK(cost_price_cents>=0),stock integer NOT NULL DEFAULT 0,min_stock integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS products_org_sku_key ON products(organization_id,lower(sku)) WHERE sku IS NOT NULL;
CREATE TABLE IF NOT EXISTS sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,client_id uuid REFERENCES clients(id) ON DELETE SET NULL,total_cents integer NOT NULL CHECK(total_cents>=0),payment_method payment_method NOT NULL,status varchar(20) NOT NULL DEFAULT 'PAID' CHECK(status IN('PAID','CANCELED')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0),cost_price_cents integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,type varchar(20) NOT NULL CHECK(type IN('ENTRY','ADJUSTMENT','SALE','RETURN')),quantity integer NOT NULL,reference_id uuid,notes text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_org_idx ON products(organization_id,name);CREATE INDEX IF NOT EXISTS sales_org_created_idx ON sales(organization_id,created_at DESC);CREATE INDEX IF NOT EXISTS stock_movements_product_idx ON stock_movements(product_id,created_at DESC);
